/* Build assets/js/search-index.js: every lesson of every course in one small
   table, so the command palette can search across courses and a lesson can
   name a prerequisite in another course ("nlp:4.3") and show its title.

   Each curriculum is loaded through the real runtime in its own context,
   because defineCourse() sets the single EC.course.

   Run: node .build/search-index.js   (check.sh runs it before the tests) */
"use strict";
const fs = require("fs"), path = require("path"), vm = require("vm");
const root = path.join(__dirname, "..");
const noop = () => {};
const el = { setAttribute: noop, removeAttribute: noop, addEventListener: noop, appendChild: noop, style: {}, classList: { toggle: noop, add: noop, remove: noop } };

const courses = {}, lessons = [];
for (const cid of fs.readdirSync(path.join(root, "courses")).sort()) {
  const sb = { console, setTimeout, requestAnimationFrame: noop,
    document: { documentElement: el, body: el, head: el, querySelector: () => null, querySelectorAll: () => [], createElement: () => el, addEventListener: noop, getElementById: () => null },
    localStorage: { getItem: () => null, setItem: noop, removeItem: noop }, navigator: {}, location: { search: "", href: "" },
    URLSearchParams: class { get() { return null; } }, matchMedia: () => ({ matches: false }) };
  sb.window = sb; vm.createContext(sb);
  for (const f of ["assets/js/highlight.js", "assets/js/render.js", "assets/js/app.js", `courses/${cid}/curriculum.js`])
    vm.runInContext(fs.readFileSync(path.join(root, f), "utf8"), sb, { filename: f });
  const C = sb.EC.course;
  courses[cid] = { title: C.title, short: C.short || C.title };
  for (const l of C.allLessons) {
    lessons.push([cid, l.id, l.num, l.title, l.module.title, (l.keywords || []).slice(0, 8).join(" "), l.ready === false ? 0 : 1]);
  }
}
const out = "/* GENERATED by .build/search-index.js -- do not edit. */\n" +
  "(function (g) { g.EC = g.EC || {}; g.EC.searchIndex = " +
  JSON.stringify({ courses, lessons }) + "; })(typeof window !== 'undefined' ? window : this);\n";
fs.writeFileSync(path.join(root, "assets/js/search-index.js"), out);
console.log(`search-index: ${lessons.length} lessons across ${Object.keys(courses).length} courses, ${Math.round(out.length / 1024)} KB`);
